10	// Author: R.K. Ellis, July, 1998.
11	// the basic process is atreepp which is the amplitude for
12	// q-(p4)+Q(-p2)+l-(-p5) ---> q+(p1)+Q-(p3)+l+(p6)
13	// All outgoing particles are right-handed,
14	// except Q(p3) which is left-handed
15	// Note all tree amplitudes divided by im wrt to BDKW paper
16	// Statement function for pp (others derived by crossing)
17	// This is an implementation of BDKW Eq.(3.10)
18	std::complex<double> atree(const char* st, int j1, int j2, int j3, int j4, int j5, int j6,
19	                            FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
20	
21	    auto tree = [&za, &zb](int j1, int j2, int j3, int j4, int j5, int j6) {
22	        return
23	          +zb(j1,j2)*za(j5,j4)*(za(j3,j1)*zb(j1,j6)+za(j3,j2)*zb(j2,j6))
24	                /(s(j2,j3)*s(j5,j6)*t(j1,j2,j3))
25	          +za(j3,j4)*zb(j6,j1)*(za(j5,j3)*zb(j3,j2)+za(j5,j4)*zb(j4,j2))
26	                /(s(j2,j3)*s(j5,j6)*t(j2,j3,j4));
27	    };
28	
29	    std::complex<double> atree_value;
30	
31	    if (st[0] == 'p' && st[1] == 'p') {
32	        atree_value = +tree(j1,j2,j3,j4,j5,j6); // @coverage-probe
33	    } else if (st[0] == 'p' && st[1] == 'm') {
34	        atree_value = -tree(j1,j3,j2,j4,j5,j6);
35	    } else if (st[0] == 's' && st[1] == 'l') {
36	        // this is not a real tree amplitude but it is an auxiliary quantity.
37	        atree_value = -tree(j3,j1,j2,j4,j5,j6);
38	    }
39	
40	    return atree_value;
41	}
